  {
   double sma20 = iMA(NULL, 0, 20, 0, MODE_SMA, PRICE_CLOSE);
   double sma200 = iMA(NULL, 0, 200, 0, MODE_SMA, PRICE_CLOSE);
   double closePrice = iClose(NULL, 0, 0);

   bool positionExists = false;
   ENUM_POSITION_TYPE currentPositionType = POSITION_TYPE_BUY;
   ulong positionTicket = 0;

   // Verifica se já existe uma posição aberta
   if (PositionsTotal() > 0)
     {
      positionTicket = PositionGetTicket(0);
      if (PositionSelectByTicket(positionTicket))
        {
         currentPositionType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);
         positionExists = true;
        }
     }

   bool isOpeningOrder = false;

   // Se a tendência é de alta e não há posição de compra aberta
   if (sma200 < closePrice && closePrice > sma20)
     {
      // Se existir uma posição de venda, ela será fechada
      if (positionExists && currentPositionType == POSITION_TYPE_SELL)
        {
         if (trade.PositionClose(positionTicket))
           {
            Print("Vendeu posição fechada com sucesso: ", positionTicket);
            positionExists = false;
            isOpeningOrder = true; // Indica que estamos abrindo uma nova ordem
           }
         else
           {
            Print("Erro ao fechar posição de venda: ", _LastError);
           }
        }

      // Abre uma posição de compra se não existe uma posição
      if (!positionExists)
        {
         if (trade.Buy(lotSize, NULL, closePrice, 0, 0, "Comprado por cruzar SMA20"))
           {
            Print("Comprado por cruzar SMA20");
            isOpeningOrder = true; // Indica que estamos abrindo uma nova ordem
           }
         else
           {
            Print("Erro ao abrir posição de compra: ", _LastError);
           }
        }
     }
   // Se a tendência é de baixa e não há posição de venda aberta
   else if (sma200 > closePrice && closePrice < sma20)
     {
      // Se existir uma posição de compra, ela será fechada
      if (positionExists && currentPositionType == POSITION_TYPE_BUY)
        {
         if (trade.PositionClose(positionTicket))
           {
            Print("Compra fechada com sucesso: ", positionTicket);
            positionExists = false;
            isOpeningOrder = true; // Indica que estamos abrindo uma nova ordem
           }
         else
           {
            Print("Erro ao fechar posição de compra: ", _LastError);
           }
        }

      // Abre uma posição de venda se não existe uma posição
      if (!positionExists)
        {
         if (trade.Sell(lotSize, NULL, closePrice, 0, 0, "Vendido por cruzar SMA20"))
           {
            Print("Vendido por cruzar SMA20");
            isOpeningOrder = true; // Indica que estamos abrindo uma nova ordem
           }
         else
           {
            Print("Erro ao abrir posição de venda: ", _LastError);
           }
        }
     }
  }
